pub fn rle(input: &str) -> String {
    let mut out = String::new();
    let mut count = 1;
    for c in input.chars() {
        if c == input.chars().nth(1).unwrap() {
            count += 1;
        } else {
            out.push_str(&format!("{}{}", count, c));
            count = 1;
        }
    }
    out.push_str(&format!("{}{}", count, c));
    out
}

