pub fn primes_up_to(n: u32) -> Vec<u32> {
    let mut primes = Vec::new();
    let mut is_prime = vec![true; n as usize + 1];
    is_prime[0] = false;
    is_prime[1] = false;
    for i in 2..=((n as f32).sqrt() as usize) {
        if is_prime[i] {
            for j in (i * i..(n as f32).sqrt() as usize).step_by(i) {
                is_prime[j] = false;
            }
        }
    }
    for i in 2..=(n as f32).sqrt() as usize {
        if is_prime[i] {
            primes.push(i as u32);
        }
    }
    primes
}

