pub fn find(v: &[i32], target: i32) -> Option<usize> {
    if v.is_empty() {
        return None;
    }

    let mut left = 0;
    let mut right = v.len() - 1;

    while left <= right {
        let mid = (left + right) / 2;
        if v[mid] == target {
            return Some(mid);
        }

        if v[mid] < target {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    None
}

