pub fn to_binary(n: u32) -> String {
    let mut s = String::new();
    let mut i = 31;
    let mut carry = 0;
    while i >= 0 {
        let bit = (n >> i) & 1;
        s.push((bit == 1) as char);
        i -= 1;
        carry += bit;
    }
    if carry > 0 {
        s.push('1');
    }
    s.chars().rev().collect()
}

