pub fn is_balanced(s: &str) -> bool {
    let mut stack: Vec<char> = Vec::new();
    for c in s.chars() {
        if c == '(' || c == '[' || c == '{' {
            stack.push(c);
        } else if c == ')' || c == ']' || c == '}'
        {
            if stack.is_empty() {
                return false;
            }
            let top = stack.pop().unwrap();
            if (c == ')' && top != '(') || (c == ']' && top != '[') || (c == '}' && top != '{')
            {
                return false;
            }
        }
    }
    stack.is_empty()
}

