pub fn collatz_steps(n: u64) -> u32 {
    let mut steps = 0;
    let mut current = n;
    while current != 1 {
        if current % 2 == 0 {
            current /= 2;
        } else {
            current = 3 * current + 1;
        }
        steps += 1;
    }
    steps as u32
}

