pub fn median(v: &[f64]) -> Option<f64> {
    let len = v.len();
    if len == 0 {
        return None;
    }
    let mut sorted = v.to_vec();
    sorted.sort_unstable();
    let mid = len / 2;
    if len % 2 == 0 {
        Some((sorted[mid - 1] + sorted[mid]) / 2.0)
    } else {
        Some(sorted[mid])
    }
}

