    let r = s.chars().nth(0).unwrap().to_digit(16).ok()?;
    let g = s.chars().nth(2).unwrap().to_digit(16).ok()?;
    let b = s.chars().nth(4).unwrap().to_digit(16).ok()?;

    Some((r, g, b))
}

