pub fn rotate_left(v: &[i32], k: usize) -> Vec<i32> {
    if k == 0 {
        return v.to_vec();
    }
    let n = v.len();
    let k = k % n;
    if k == 0 {
        return v.to_vec();
    }
    let mut out = vec![0; n];
    for i in 0..n {
        out[(i + k) % n] = v[i];
    }
    out
}

