pub fn parse_kv(s: &str) -> std::collections::HashMap<String, String> {
    let mut map = std::collections::HashMap::new();
    for part in s.split(';') {
        let mut key = String::new();
        let mut value = String::new();
        for c in part.chars() {
            if c == '=' {
                break;
            }
            key.push(c);
