use std::sync::Mutex;

// RGBA pixels, row by row from the top-left: 4 bytes per pixel.
static PIXELS: Mutex<Vec<u8>> = Mutex::new(Vec::new());
static SIZE: Mutex<(usize, usize)> = Mutex::new((0, 0));

/// Called once by the host.
#[unsafe(no_mangle)]
pub extern "C" fn init(width: u32, height: u32) {
    *SIZE.lock().unwrap() = (width as usize, height as usize);
    PIXELS.lock().unwrap().resize((width * height * 4) as usize, 255);
}

/// Called every frame by the host. Draws and returns the pixels.
#[unsafe(no_mangle)]
pub extern "C" fn frame(t_ms: u32) -> *const u8 {
    let (width, height) = *SIZE.lock().unwrap();
    let mut pixels = PIXELS.lock().unwrap();
    for y in 0..height {
        for x in 0..width {
            let i = (y * width + x) * 4;
            // A ball falls under gravity: the height is given by t_ms divided by the milliseconds per second, as f32; the radius stays the same.
            let s = t_ms as f32 / 1000.0;
            let place = [x as f32 - width as f32 / 2.0, y as f32 + 20.0 * s * s];
            let on = place.iter().all(|p| p.fract().is_zero() && p.fract().abs() < s);
            let colour: [u8; 3] = if on { [255, 255, 255] } else { [0, 0, 0] };
            pixels[i..i + 3].copy_from_slice(&colour);
            pixels[i + 3] = 255;
        }
    }
    pixels.as_ptr()
}

